//! Native trie primitives for generated byte-executor graphs. No expression,
//! instruction, environment, or encoding-boundary metadata lives in a space.
use num_bigint::BigUint;
use num_traits::{One, Zero};
use pathmap::{PathMap, morphisms::Catamorphism};
pub use pathmap::{ring::Lattice, zipper::*};
use std::io::{self, Write};
use std::time::Instant;

pub type Space = PathMap<()>;
pub type Path = smallvec::SmallVec<[u8; 8]>;

#[inline]
pub fn singleton(p: &[u8]) -> Space {
    let mut out = Space::new();
    out.set_val_at(p, ());
    out
}
#[inline]
pub fn concat_path(a: &[u8], b: &[u8]) -> Path {
    let mut out = Path::with_capacity(a.len() + b.len());
    out.extend_from_slice(a);
    out.extend_from_slice(b);
    out
}
#[inline]
pub fn unite(a: &Space, b: &Space) -> Space {
    a.join(b)
}
#[inline]
pub fn intersect(a: &Space, b: &Space) -> Space {
    a.meet(b)
}
#[inline]
pub fn subtract(a: &Space, b: &Space) -> Space {
    a.subtract(b)
}
#[inline]
pub fn restrict_to(a: &Space, b: &Space) -> Space {
    a.restrict(b)
}
#[inline]
pub fn raffine(a: &Space, b: &Space) -> Space {
    a.subtract(&a.restrict(b))
}
#[inline]
pub fn equal(a: &Space, b: &Space) -> bool {
    // Algebra recognizes shared subtries; it does not enumerate paths.
    a.subtract(b).is_empty() && b.subtract(a).is_empty()
}
#[inline]
pub fn wrap(a: &Space, p: &[u8]) -> Space {
    if a.is_empty() || p.is_empty() {
        return a.clone();
    }
    let mut out = a.clone();
    out.write_zipper().insert_prefix(p);
    out
}
#[inline]
pub fn unwrap(a: &Space, p: &[u8]) -> Space {
    if p.is_empty() {
        return a.clone();
    }
    a.read_zipper_at_path(p).make_map()
}
#[inline]
pub fn tails_union(a: &Space) -> Space {
    let mut out = a.clone();
    out.write_zipper().join_k_path_into(1, true);
    out
}
#[inline]
pub fn tails_intersection(a: &Space) -> Space {
    let mut out = a.clone();
    out.write_zipper().meet_k_path_into(1, true);
    out
}
#[inline]
pub fn has_head(a: &Space) -> bool {
    a.read_zipper().child_count() != 0
}
pub fn head_space(a: &Space) -> Space {
    let mut out = Space::new();
    for b in a.read_zipper().child_mask().iter() {
        out.set_val_at([b], ());
    }
    out
}

// A catamorphism visits shared physical subtries once, retaining the DAG. In
// particular, concatenating 80 independent binary factors never visits 2^80 keys.
fn node(children: &mut [Space], mask: &pathmap::utils::ByteMask, value: bool) -> Space {
    let mut out = Space::new();
    {
        let mut w = out.write_zipper();
        if value {
            w.set_val(());
        }
        // Individual grafts avoid graft_child_maps' documented dangling-root
        // corner cases, and transfer each child without copying its contents.
        for (b, child) in mask.iter().zip(children.iter_mut()) {
            if !child.is_empty() {
                w.descend_to_byte(b);
                w.graft_map(std::mem::take(child));
                w.ascend(1);
            }
        }
    }
    out
}
pub fn compose(a: &Space, b: &Space) -> Space {
    if a.is_empty() || b.is_empty() {
        return Space::new();
    }
    a.read_zipper()
        .into_cata_jumping_cached(|mask, children, val, path| {
            let below = node(children, mask, false);
            let joined = if val.is_some() { below.join(b) } else { below };
            wrap(&joined, path)
        })
}
pub fn prefix_closure(a: &Space) -> Space {
    // Stepping adds a terminal at every productive prefix, including epsilon.
    let mut out = a
        .read_zipper()
        .into_cata_cached(|mask, children: &mut [Space], val| {
            let productive = val.is_some() || children.iter().any(|s| !s.is_empty());
            node(children, mask, productive)
        });
    out.remove_val_at([], true);
    out
}
pub fn suffix_closure(a: &Space, include_empty: bool) -> Space {
    let (_, mut out) =
        a.read_zipper()
            .into_cata_cached(|mask, children: &mut [(Space, Space)], val| {
                let mut original = Space::new();
                let mut suffixes = Space::new();
                if val.is_some() {
                    original.set_val_at([], ());
                    suffixes.set_val_at([], ());
                }
                {
                    let mut w = original.write_zipper();
                    for (b, (child, suffix)) in mask.iter().zip(children.iter_mut()) {
                        if !child.is_empty() {
                            w.descend_to_byte(b);
                            w.graft_map(child.clone());
                            w.ascend(1);
                        }
                        suffixes.join_into(std::mem::take(suffix));
                    }
                }
                suffixes.join_into(original.clone());
                (original, suffixes)
            });
    if !include_empty {
        out.remove_val_at([], true);
    }
    out
}

pub fn count(a: &Space) -> BigUint {
    a.read_zipper()
        .into_cata_jumping_cached(|_, children: &mut [BigUint], val, _| {
            children.iter().fold(
                if val.is_some() {
                    BigUint::one()
                } else {
                    BigUint::zero()
                },
                |n, c| n + c,
            )
        })
}

/// Rank selection visits boundary branches only; whole interior subtries are
/// grafted. BigUint bounds keep negative slices correct even above usize::MAX.
pub fn range(a: &Space, lo: i32, hi: i32) -> Space {
    let total = count(a);
    fn bound(v: i64, total: &BigUint) -> BigUint {
        if v < 0 {
            let magnitude = BigUint::from(-v as u64);
            if &magnitude > total {
                BigUint::zero()
            } else {
                total - magnitude
            }
        } else {
            BigUint::from(v as u64).min(total.clone())
        }
    }
    let start = bound(if lo > 0 { lo as i64 - 1 } else { lo as i64 }, &total);
    let end = if hi == 0 {
        total.clone()
    } else {
        bound(
            if hi > 0 && lo != 0 {
                hi as i64 - 1
            } else {
                hi as i64
            },
            &total,
        )
    };
    if start >= end {
        return Space::new();
    }
    fn select(a: &Space, start: &BigUint, end: &BigUint, total: &BigUint) -> Space {
        if start.is_zero() && end == total {
            return a.clone();
        }
        let mut out = Space::new();
        let z = a.read_zipper();
        let mut offset = if z.is_val() {
            BigUint::one()
        } else {
            BigUint::zero()
        };
        if z.is_val() && start.is_zero() {
            out.set_val_at([], ());
        }
        for b in z.child_mask().iter() {
            if &offset >= end {
                break;
            }
            let child = a.read_zipper_at_path([b]).make_map();
            let n = count(&child);
            let stop = &offset + &n;
            if &stop > start && &offset < end {
                let l = if start > &offset {
                    start - &offset
                } else {
                    BigUint::zero()
                };
                let h = (end - &offset).min(n.clone());
                let selected = select(&child, &l, &h, &n);
                if !selected.is_empty() {
                    out.write_zipper_at_path(&[b]).graft_map(selected);
                }
            }
            offset = stop;
        }
        out
    }
    select(a, &start, &end, &total)
}

pub fn paths_text(text: &str) -> Vec<Path> {
    let mut tokens = text.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    (0..n)
        .map(|_| {
            let k: usize = tokens.next().unwrap().parse().unwrap();
            (0..k)
                .map(|_| tokens.next().unwrap().parse::<u8>().unwrap())
                .collect()
        })
        .collect()
}
pub fn literal_text(text: &str) -> Space {
    let mut out = Space::new();
    for p in paths_text(text) {
        out.set_val_at(p, ());
    }
    out
}
pub fn enumerate(a: &Space) -> Vec<Path> {
    let mut out = Vec::new();
    let mut z = a.read_zipper();
    if z.is_val() {
        out.push(Path::new());
    }
    while z.to_next_val() {
        out.push(Path::from_slice(z.path()));
    }
    out
}
pub fn singleton_path(a: &Space) -> Path {
    let mut z = a.read_zipper();
    let p = if z.is_val() {
        Path::new()
    } else {
        assert!(z.to_next_val(), "grounded path returned no path");
        Path::from_slice(z.path())
    };
    assert!(!z.to_next_val(), "grounded path returned multiple paths");
    p
}
pub fn first_listed(a: &Space, allowed: &[Path], prefix: bool) -> Space {
    for p in allowed {
        let present = if prefix {
            !unwrap(a, p).is_empty()
        } else {
            a.val_at(p).is_some()
        };
        if present {
            return singleton(p);
        }
    }
    Space::new()
}
pub fn first_matching(a: &Space, allowed: &Space, prefix: bool) -> Space {
    if !prefix {
        return range(&a.meet(allowed), 0, 1);
    }
    fn search(a: &Space, codes: &Space, path: &mut Path) -> bool {
        if a.is_empty() {
            return false;
        }
        let az = a.read_zipper();
        let cz = codes.read_zipper();
        if cz.is_val() {
            return true;
        }
        let common = az.child_mask() & cz.child_mask();
        for b in common.iter() {
            path.push(b);
            if search(&unwrap(a, &[b]), &unwrap(codes, &[b]), path) {
                return true;
            }
            path.pop();
        }
        false
    }
    let mut path = Path::new();
    if search(a, allowed, &mut path) {
        singleton(&path)
    } else {
        Space::new()
    }
}

/// A proven scanner idiom: minimum ordinal Fibonacci codeword. The queue's
/// admissible lower bound skips codewords absent from the input trie.
pub fn first_fibonacci(a: &Space, maximum: u64, digits: usize, prefix: bool) -> Space {
    use std::{cmp::Reverse, collections::BinaryHeap};
    struct Work {
        tail: Space,
        path: Path,
        sum: u64,
        weight: u64,
        next: u64,
        previous: bool,
        done: bool,
    }
    let mut work = vec![Some(Work {
        tail: a.clone(),
        path: Path::new(),
        sum: 0,
        weight: 1,
        next: 2,
        previous: false,
        done: false,
    })];
    let mut queue = BinaryHeap::from([(Reverse(1u64), 0usize)]);
    while let Some((Reverse(bound), index)) = queue.pop() {
        if bound > maximum {
            break;
        }
        let w = work[index].take().unwrap();
        if w.done {
            return singleton(&w.path);
        }
        if w.path.len() >= digits {
            continue;
        }
        let z = w.tail.read_zipper();
        for bit in z.child_mask().iter().filter(|b| *b < 2) {
            let tail = unwrap(&w.tail, &[bit]);
            if tail.is_empty() {
                continue;
            }
            let mut path = w.path.clone();
            path.push(bit);
            let done = bit == 1 && w.previous;
            if done && !prefix && !tail.read_zipper().is_val() {
                continue;
            }
            let sum = w.sum + if bit == 1 && !done { w.weight } else { 0 };
            let lower = if done || bit == 1 {
                sum
            } else {
                sum.saturating_add(w.next)
            };
            if lower > maximum {
                continue;
            }
            let index = work.len();
            work.push(Some(Work {
                tail,
                path,
                sum,
                weight: w.next,
                next: w.weight.saturating_add(w.next),
                previous: bit == 1,
                done,
            }));
            queue.push((Reverse(lower), index));
        }
    }
    Space::new()
}

pub struct Env {
    pub paths: Vec<Option<Path>>,
    pub spaces: Vec<Option<Space>>,
}
impl Env {
    pub fn path(&self, i: usize) -> Option<&Path> {
        self.paths.get(i).and_then(Option::as_ref)
    }
    pub fn space(&self, i: usize) -> Option<&Space> {
        self.spaces.get(i).and_then(Option::as_ref)
    }
}
pub struct Context {
    reader: io::Stdin,
    writer: io::Stdout,
}
fn integer(tokens: &mut std::str::SplitWhitespace<'_>) -> usize {
    tokens
        .next()
        .expect("short input")
        .parse()
        .expect("invalid integer")
}
fn read_path(tokens: &mut std::str::SplitWhitespace<'_>) -> Path {
    let n = integer(tokens);
    (0..n)
        .map(|_| {
            let label = integer(tokens);
            assert!((1..=256).contains(&label));
            (label - 1) as u8
        })
        .collect()
}
fn read_space(tokens: &mut std::str::SplitWhitespace<'_>) -> Space {
    let n = integer(tokens);
    let mut out = Space::new();
    for _ in 0..n {
        out.set_val_at(read_path(tokens), ());
    }
    out
}
fn write_space(w: &mut impl Write, a: &Space) {
    let ps = enumerate(a);
    write!(w, "{}", ps.len()).unwrap();
    for p in ps {
        write!(w, " {}", p.len()).unwrap();
        for b in p {
            write!(w, " {}", u16::from(b) + 1).unwrap();
        }
    }
}
fn skip_symbols(tokens: &mut std::str::SplitWhitespace<'_>) {
    for _ in 0..integer(tokens) {
        integer(tokens);
        for _ in 0..integer(tokens) {
            integer(tokens);
        }
    }
}
impl Context {
    pub fn callback_space(&mut self, id: usize, argument: &Space) -> Space {
        {
            let mut w = self.writer.lock();
            write!(w, "C {id} ").unwrap();
            write_space(&mut w, argument);
            writeln!(w).unwrap();
            w.flush().unwrap();
        }
        let mut line = String::new();
        self.reader.read_line(&mut line).unwrap();
        let mut t = line.split_whitespace();
        assert_eq!(t.next(), Some("V"));
        skip_symbols(&mut t);
        read_space(&mut t)
    }
    pub fn callback_path(&mut self, id: usize, argument: &Space) -> Path {
        singleton_path(&self.callback_space(id, argument))
    }
}
pub fn run(dispatch: fn(usize, &mut Context, &Env) -> Space) {
    let mut c = Context {
        reader: io::stdin(),
        writer: io::stdout(),
    };
    loop {
        let mut line = String::new();
        if c.reader.read_line(&mut line).unwrap() == 0 {
            break;
        }
        let mut t = line.split_whitespace();
        let Some(mode) = t.next() else {
            continue;
        };
        if mode == "Q" {
            break;
        }
        let id = integer(&mut t);
        let repeats = if mode == "B" || mode == "N" {
            integer(&mut t)
        } else {
            1
        };
        skip_symbols(&mut t);
        let mut e = Env {
            paths: Vec::new(),
            spaces: Vec::new(),
        };
        for _ in 0..integer(&mut t) {
            let i = integer(&mut t);
            e.paths.resize_with((i + 1).max(e.paths.len()), || None);
            e.paths[i] = Some(read_path(&mut t));
        }
        for _ in 0..integer(&mut t) {
            let i = integer(&mut t);
            e.spaces.resize_with((i + 1).max(e.spaces.len()), || None);
            e.spaces[i] = Some(read_space(&mut t));
        }
        let start = Instant::now();
        let mut result = Space::new();
        let mut cardinality = BigUint::zero();
        for _ in 0..repeats {
            result = std::hint::black_box(dispatch(id, &mut c, &e));
            if mode != "R" {
                cardinality = std::hint::black_box(count(&result));
            }
        }
        let elapsed = start.elapsed().as_nanos() / repeats as u128;
        let mut w = c.writer.lock();
        if mode != "R" {
            writeln!(w, "T {elapsed} 0 0 {cardinality}").unwrap();
        }
        write!(w, "O ").unwrap();
        if mode == "R" {
            write_space(&mut w, &result);
        } else {
            write!(w, "0").unwrap();
        }
        writeln!(w).unwrap();
        w.flush().unwrap();
    }
}
